template <bool threads, int inst>
class __my_default_alloc_template
{
    union obj { union obj *free_list_link; char data[1]; };
public:
    static obj *free_list[16];
    static void *refill(unsigned int);
    static void *allocate(unsigned int n)
    {
        obj **list = free_list + ((n + 7) / 8 - 1);
        obj *result = *list;
        if (result == 0)
            return refill(n);
        *list = result->free_list_link;
        return result;
    }
};

template<class T> class my_allocator {};

template<class T, class Alloc>
class list
{
    struct node_base { node_base *next; node_base *prev; };
    struct node : node_base { T data; };
    node_base *sentinel;
public:
    void push_back(const T &value)
    {
        node *entry = (node *)__my_default_alloc_template<false, 0>::allocate(sizeof(node));
        if (&entry->data)
            entry->data = value;
        entry->next = sentinel;
        entry->prev = sentinel->prev;
        sentinel->prev->next = entry;
        sentinel->prev = entry;
    }
};

